package de.craftolution.craftoplugin.module.playtime.playtime;

import de.craftolution.craftoplugin.service.playerstorage.StoredPlayer;

import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class Playtime {

	private final StoredPlayer player;
	private final long minutesPlayed;
	private long millisPlayed;
	private Lock lock = new ReentrantLock();

	Playtime(StoredPlayer player, long minutesPlayed) {
		this.player = player;
		this.minutesPlayed = minutesPlayed;
	}

	public void addMillis(long millis) {
		try {
			this.lock.lock();
			this.millisPlayed = this.millisPlayed + millis;
		}
		finally {
			this.lock.unlock();
		}
	}

	public StoredPlayer getPlayer() {
		return player;
	}

	public long getTotalMinutesPlayed() {
		long newMinutes = this.millisPlayed / 1000L / 60L;
		return this.minutesPlayed + newMinutes;
	}

	public long getRelativeMinutesPlayed() {
		long totalHours = getTotalHoursPlayed();
		long totalMinutes = getTotalMinutesPlayed();

		return totalMinutes - (totalHours * 60L);
	}

	public long getTotalHoursPlayed() {
		return getTotalMinutesPlayed() / 60L;
	}

	@Override
	public String toString() {
		return "Playtime(" + player + ", " + minutesPlayed + ", " + millisPlayed + ")";
	}


}

