    @Test

    public void testSetGetHttp2Port() {



        JxseHttp2TransportConfiguration Temp = new JxseHttp2TransportConfiguration();



        assertTrue(Temp.getHttp2Port()==-1);



        Temp.setHttp2Port(3333);

        assertTrue(Temp.getHttp2Port()==3333);



