/** Numero del palito que se mueve */
  private int palito;
  /** Direccion del movimiento: -1 izquierda, +1 derecha */
  private int direccion;
  /** Identificador de la jugada */
  private String id;

  /**
   * Constructor principal.
   * @param palito Numero del palito que se mueve.
   * @param direccion Direccion del movimiento (-1 izquierda, +1 derecha).
   */
  public Move(final int palito, final int direccion) {
    this.palito = palito;
    this.direccion = direccion;
    this.id = palito + ((direccion == -1) ? "L" : "R");
  }

  /**
   * Constructor a partir del identificador.
   * @param id Identificador de la jugada.
   */
  public Move(final String id) {
    this.id = id;
    final char dirChar = id.charAt(id.length() - 1);
    this.direccion = (dirChar == 'L') ? -1 : 1;
    this.palito = Integer.parseInt(id.substring(0, id.length() - 1));
  }

